import random
from torch.utils.data import Dataset, DataLoader, Sampler


class CharTokenizer:
    """极简字符级分词器，只实现题目需要的那一种调用约定：
    tok(text, truncation=True, max_length=L) -> {"input_ids": [...]}
    真机换成 transformers 的 AutoTokenizer.from_pretrained(...) 即可，Dataset 无需改动。"""

    def __init__(self):
        self.vocab = {"<pad>": 0, "<unk>": 1}
        self.pad_id = 0
        self.unk_id = 1

    def _id(self, ch):
        if ch not in self.vocab:
            self.vocab[ch] = len(self.vocab)          # 动态扩表：保证任何字符都可编码
        return self.vocab[ch]

    def __call__(self, text, truncation=True, max_length=512):
        ids = [self._id(ch) for ch in text]
        if truncation:
            ids = ids[:max_length]                    # 先截断，再去 collate 里 pad
        return {"input_ids": ids or [self.unk_id]}    # 空串退化成一个 unk，避免长度 0


class MyDataset(Dataset):
    def __init__(self, samples, tokenizer, max_len=512):
        self.samples, self.tok, self.max_len = samples, tokenizer, max_len

    def __len__(self):
        return len(self.samples)

    def __getitem__(self, idx):
        s = self.samples[idx]
        ids = self.tok(s["text"], truncation=True, max_length=self.max_len)["input_ids"]
        return {"input_ids": ids, "label": s["label"]}

    def lengths(self):
        """给 BucketSampler 用的真实长度（截断后的 token 数）。"""
        return [min(len(self.tok(s["text"], truncation=True,
                                max_length=self.max_len)["input_ids"]), self.max_len)
                for s in self.samples]


def collate_fn(batch, pad_id=0):
    """关键：变长序列只 pad 到本 batch 最长，并生成 attention_mask；
    labels 侧的 padding 位置必须置 -100（cross_entropy 的 ignore_index）。"""
    if not batch:
        raise ValueError("empty batch：sampler / batch_size 配置有误，不要静默返回空张量")
    maxlen = max(len(b["input_ids"]) for b in batch)   # 本 batch 最长，不是全局最长
    input_ids, attn, labels = [], [], []
    for b in batch:
        ids = b["input_ids"]
        pad = maxlen - len(ids)
        input_ids.append(ids + [pad_id] * pad)
        attn.append([1] * len(ids) + [0] * pad)
        labels.append(ids + [-100] * pad)
    return {"input_ids": input_ids, "attention_mask": attn, "labels": labels}


class BucketSampler(Sampler):
    """按长度分桶：全局按长度升序 -> 每 batch_size 个切一桶 -> 打乱桶顺序。
    等长成批让 padding 浪费最小，桶间 shuffle 保住随机性（人工 pitfalls 第三条）。"""

    def __init__(self, lengths, batch_size, shuffle=True, shuffle_within_batch=False):
        if batch_size <= 0:
            raise ValueError("batch_size 必须为正")
        if not lengths:
            raise ValueError("lengths 为空：没有样本可分桶")
        order = sorted(range(len(lengths)), key=lambda i: lengths[i])
        self.batches = [order[i:i + batch_size] for i in range(0, len(order), batch_size)]
        self.shuffle = shuffle
        self.shuffle_within_batch = shuffle_within_batch

    def __iter__(self):
        bs = [b[:] for b in self.batches]        # 浅拷贝：不污染 self.batches，保证多轮可复现
        if self.shuffle:
            random.shuffle(bs)                   # 漏掉这步 = 每轮顺序完全相同
        for b in bs:
            if self.shuffle_within_batch:
                random.shuffle(b)                # 桶内再打乱（默认关闭，与人工实现一致）
            yield from b

    def __len__(self):
        return sum(len(b) for b in self.batches)


if __name__ == "__main__":
    random.seed(0)
    texts = ["深度学习", "a", "推荐系统与向量召回", "ab", "大模型对齐", "abc"]
    samples = [{"text": t, "label": i % 2} for i, t in enumerate(texts)]
    tok = CharTokenizer()
    ds = MyDataset(samples, tok, max_len=4)
    sampler = BucketSampler(ds.lengths(), batch_size=2)
    loader = DataLoader(ds, batch_size=2, sampler=sampler,
                        collate_fn=lambda b: collate_fn(b, pad_id=tok.pad_id),
                        num_workers=0, pin_memory=False)

    seen = 0
    for step, batch in enumerate(loader):
        lens = [sum(m) for m in batch["attention_mask"]]
        L = len(batch["input_ids"][0])
        assert all(len(row) == L for row in batch["input_ids"]), "batch 内必须等长"
        assert len(batch["labels"]) == len(batch["attention_mask"]) == len(batch["input_ids"])
        assert L == max(lens), "必须只 pad 到本 batch 最长"
        n_pad = sum(1 for row in batch["labels"] for x in row if x == -100)
        assert n_pad == sum(L - n for n in lens), "labels 的 pad 位必须恰好是 -100"
        seen += len(batch["input_ids"])
        print("step", step, "| L =", L, "| 有效长度", lens, "| 被忽略", n_pad)
    assert seen == len(ds), "sampler 必须恰好覆盖每个样本一次"
    print("ok: 覆盖", seen, "条样本，桶划分", [len(b) for b in sampler.batches])
